<h2>Project compound growth with monthly contributions</h2><p class="lead">Estimate a future balance from starting principal, monthly additions, annual rate and years.</p><div class="form-grid"><div class="field"><label for="principal">Starting principal</label><input id="principal" type="number" min="0" step="0.01" value="10000"></div><div class="field"><label for="monthly">Monthly contribution</label><input id="monthly" type="number" min="0" step="0.01" value="500"></div><div class="field"><label for="rate">Annual rate (%)</label><input id="rate" type="number" step="0.01" value="7"></div><div class="field"><label for="years">Years</label><input id="years" type="number" min="0" step="1" value="10"></div></div><div class="tool-actions"><button class="btn btn-primary" id="calc">Calculate</button></div><div class="result-box"><div class="result-grid"><div class="metric"><span>Estimated final balance</span><strong id="balance">—</strong></div><div class="metric"><span>Total contributions</span><strong id="contrib">—</strong></div><div class="metric"><span>Estimated growth</span><strong id="growth">—</strong></div></div></div><p class="helper">Assumes monthly compounding and contributions made at the end of each month. It is a mathematical scenario, not a return forecast.</p>
<script>(()=>{const $=i=>document.getElementById(i),n=i=>parseFloat($(i).value)||0,m=x=>'$'+x.toLocaleString(undefined,{minimumFractionDigits:2,maximumFractionDigits:2});function go(){let bal=n('principal'),monthly=n('monthly'),r=n('rate')/100/12,months=Math.max(0,Math.round(n('years')*12));for(let i=0;i<months;i++){bal*=1+r;bal+=monthly}const contributions=n('principal')+monthly*months;$('balance').textContent=m(bal);$('contrib').textContent=m(contributions);$('growth').textContent=m(bal-contributions)}document.querySelectorAll('input').forEach(x=>x.addEventListener('input',go));$('calc').onclick=go;go()})();</script>
